#!/usr/bin/env python3
# AI: below section was generated by an AI
"""
场景名 -> 三色渐变配方（静态氛围色）

为什么存在：用户说「客厅来个热带海岸」「樱花那种粉」时，不需要联网找参考图，
本表 14 组配色直接出一份可下发的配方，走既有的 apply_recipe.py 落到局域网 WLED。

渲染方式（源码依据见 references/scene-palettes.md）：
  fx 161 Shimmer + sx=0   -> position 锁死在段中心，真正静止
  pal 4 = (ter, sec, prim) -> col[2]=起点色, col[1]=中间色, col[0]=终点色
  c1 = 255                 -> radius ≈ 2×SEGLEN，整条都在带内

用法：
    python3 scene_palette.py --list
    python3 scene_palette.py "热带海岸"
    python3 scene_palette.py "樱花" --bri 180 --leds 70
    python3 scene_palette.py "热带海岸" --emit state
    python3 scene_palette.py "热带海岸" --apply
    python3 scene_palette.py "热带海岸" --profile breath --apply
"""
from __future__ import annotations

import argparse
import json
import os
import subprocess
import sys
import tempfile
from pathlib import Path

SCRIPT_DIR = Path(__file__).resolve().parent
SKILL_DIR = SCRIPT_DIR.parent
CONFIG_PATH = SKILL_DIR / "config.json"

# 场景表：名字 -> (起点色, 终点色, 默认亮度, 别名)
SCENES: dict[str, tuple[str, str, int, tuple[str, ...]]] = {
    "红苹果":     ("#DC2626", "#FF6B6B", 200, ("苹果", "果红", "果实")),
    "热带海岸":   ("#00B4D8", "#FFD166", 210, ("海边日落", "海岛", "马尔代夫", "沙滩日落", "热带")),
    "春日樱花":   ("#FFB7C5", "#FFF5E6", 190, ("樱花", "春天", "赏樱", "粉色浪漫")),
    "蓝白幻想":   ("#0095D9", "#FFFFFF", 210, ("卡通", "蓝白", "梦幻蓝")),
    "多巴胺治愈": ("#FF9A76", "#FFEAA7", 200, ("治愈", "温馨", "生日", "暖调", "多巴胺")),
    "森林晨光":   ("#42802B", "#91D099", 195, ("森林", "晨光", "绿意", "自然")),
    "日出朝霞":   ("#F3541C", "#F1AB27", 210, ("日出", "朝霞", "晨曦", "黄昏")),
    "深海珍珠":   ("#2D63AD", "#05A99E", 200, ("深海", "海底", "静谧蓝")),
    "极光之夜":   ("#A1B1C8", "#C8C2CC", 185, ("极光", "科幻", "冷调", "银紫")),
    "金色年华":   ("#556A95", "#FFC044", 205, ("金色", "高级感", "轻奢")),
    "秋日枫叶":   ("#A8EFFE", "#F25431", 200, ("秋天", "枫叶", "秋意")),
    "冰川幽蓝":   ("#88B2ED", "#D9F3FD", 190, ("冰川", "冰蓝", "清爽", "冷白")),
    "萤火虫夜":   ("#95FF89", "#EDF468", 185, ("萤火虫", "荧光", "夜景", "嫩黄")),
    "玫瑰花语":   ("#EF6A85", "#FFC6C5", 195, ("玫瑰", "浪漫", "粉红", "告白")),
}

DEFAULT_LEDS = 70


# ---------------------------------------------------------------- 颜色工具
def hex_to_rgb(value: str) -> tuple[int, int, int]:
    s = value.strip().lstrip("#")
    if len(s) == 3:
        s = "".join(ch * 2 for ch in s)
    if len(s) != 6:
        raise ValueError(f"颜色格式不对：{value!r}（要 #RRGGBB）")
    return int(s[0:2], 16), int(s[2:4], 16), int(s[4:6], 16)


def rgb_to_hex(rgb: tuple[int, int, int]) -> str:
    return "#%02X%02X%02X" % rgb


def midpoint(a: tuple[int, int, int], b: tuple[int, int, int]) -> tuple[int, int, int]:
    """线性光空间取中点。

    为什么不用 HSV 插值：色相走「最短路径」会跑出歧义结果 —— 蓝(#00B4D8)→金(#FFD166)
    的色相最短路径经过绿色，会得到一块荧光绿，完全不是「海边日落」。
    光混合是加性的，线性光平均才是物理上正确的中间色。
    """
    def to_linear(c: int) -> float:
        x = c / 255.0
        return x ** 2.2

    def to_srgb(x: float) -> int:
        return round(255 * (max(0.0, min(1.0, x)) ** (1 / 2.2)))

    return tuple(  # type: ignore[return-value]
        to_srgb((to_linear(x) + to_linear(y)) / 2) for x, y in zip(a, b)
    )


# ---------------------------------------------------------------- 场景解析
def resolve(query: str) -> tuple[str, str, str]:
    """返回 (场景名, 起点色, 终点色)。命中不到就抛错并列出候选。"""
    q = query.strip().replace(" ", "")
    if not q:
        raise KeyError("场景名为空")

    if q in SCENES:
        name = q
    else:
        hits = [n for n, (_, _, _, al) in SCENES.items()
                if q in n or any(q in a or a in q for a in al)]
        if not hits:
            # 反向：用户输入比场景名长，例如「来个热带海岸那种日落」
            hits = [n for n in SCENES if n in q]
        if len(hits) == 1:
            name = hits[0]
        elif len(hits) > 1:
            raise KeyError(f"「{query}」命中多个场景：{('、'.join(hits))}，请说完整名字")
        else:
            raise KeyError(f"没有「{query}」这个场景。用 --list 看全部 {len(SCENES)} 个")

    start, end, _, _ = SCENES[name]
    return name, start, end


# ---------------------------------------------------------------- 配方生成
def device_led_count() -> int:
    try:
        cfg = json.loads(CONFIG_PATH.read_text(encoding="utf-8"))
        n = int(((cfg.get("layout") or {}).get("total_leds")) or 0)
        return n if n > 0 else DEFAULT_LEDS
    except (OSError, ValueError, TypeError):
        return DEFAULT_LEDS


def build_segment(start_hex: str, end_hex: str, leds: int, profile: str,
                  mid_hex: str | None) -> dict:
    a = hex_to_rgb(start_hex)
    b = hex_to_rgb(end_hex)
    mid = hex_to_rgb(mid_hex) if mid_hex else midpoint(a, b)

    # pal 4 = (ter, sec, prim) —— 起点放 col[2]，中间色 col[1]，终点 col[0]
    col = [list(b), list(mid), list(a)]
    sx = 0 if profile == "still" else 40

    return {
        "start": 0,
        "stop": leds,
        "fx": 161,          # Shimmer：sx=0 时位置锁死，整条铺满调色板
        "sx": sx,
        "ix": 0,            # Interval 是「跑完一趟后的停顿」，静止档无意义，置 0
        "pal": 4,           # Color Gradient（混合渐变，不是三段分明）
        "c1": 255,          # 带宽拉满：radius ≈ 2×SEGLEN，整条都在带内
        "c2": 0,            # Granular 调制器关闭
        "bri": 255,
        "mi": False,
        "of": 0,
        "bm": 0,
        "o1": False,
        "o2": False,
        "o3": False,
        "col": col,
    }


def build_recipe(name: str, start_hex: str, end_hex: str, leds: int,
                 bri: int, profile: str, mid_hex: str | None) -> dict:
    seg = build_segment(start_hex, end_hex, leds, profile, mid_hex)
    return {
        "name": f"场景 · {name}",
        "type": "static-ambient",
        "bri": bri,
        "colors": seg["col"],
        "segments": [seg],
        "_design": {
            "mode": "静态氛围色（不是 1 分钟动态配方）",
            "palette": f"起点 {start_hex} → 中间 {rgb_to_hex(tuple(seg['col'][1]))} → 终点 {end_hex}",
            "render": ("Shimmer sx=0：position=(SEGLEN<<7) 锁死在段中心，静止"
                       if profile == "still" else
                       "Shimmer sx=40：极慢呼吸推移"),
            "ordering": "pal 4 = (ter, sec, prim) ⇒ col[2]=起点、col[1]=中间、col[0]=终点",
            "coverage": f"单段 0..{leds}，整条覆盖",
        },
    }


# ---------------------------------------------------------------- 输出
def emit_state(recipe: dict) -> dict:
    seg = dict(recipe["segments"][0])
    seg["id"] = 0
    return {"on": True, "bri": recipe["bri"], "transition": 0, "seg": [seg]}


def apply_recipe(recipe: dict, dry_run: bool) -> int:
    fd, tmp = tempfile.mkstemp(prefix="scene-", suffix=".json")
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as f:
            json.dump(recipe, f, ensure_ascii=False, indent=2)
        cmd = [sys.executable, str(SCRIPT_DIR / "apply_recipe.py"), tmp]
        if dry_run:
            cmd.append("--dry-run")
        return subprocess.call(cmd, cwd=str(SKILL_DIR))
    finally:
        try:
            os.unlink(tmp)
        except OSError:
            pass


def main() -> int:
    ap = argparse.ArgumentParser(
        description="场景名 -> 三色渐变配方（静态氛围色）",
        formatter_class=argparse.RawDescriptionHelpFormatter,
    )
    ap.add_argument("scene", nargs="?", help="场景名或别名，例如 热带海岸 / 樱花 / 生日")
    ap.add_argument("--list", action="store_true", help="列出全部场景")
    ap.add_argument("--emit", choices=("recipe", "state"), default="recipe",
                    help="recipe = 完整配方（默认）；state = 可直接 POST 的 /json/state 片段")
    ap.add_argument("--bri", type=int, default=None, help="全局亮度 1..255，默认取场景值")
    ap.add_argument("--leds", type=int, default=None, help="灯珠数，默认读 config.json")
    ap.add_argument("--mid", default=None, help="手动指定中间色 #RRGGBB")
    ap.add_argument("--profile", choices=("still", "breath"), default="still",
                    help="still = 完全静止（默认）；breath = 极慢呼吸")
    ap.add_argument("--apply", action="store_true", help="直接下发到局域网 WLED")
    ap.add_argument("--dry-run", action="store_true", help="配合 --apply：只打印不写入")
    args = ap.parse_args()

    if args.list or not args.scene:
        print(f"{len(SCENES)} 个场景（起点 → 终点）：")
        for n, (s, e, b, al) in SCENES.items():
            print(f"  {n:<8} {s} → {e}  bri≈{b}  别名：{'、'.join(al)}")
        return 0

    try:
        name, start_hex, end_hex = resolve(args.scene)
    except KeyError as exc:
        print(f"错误：{exc}", file=sys.stderr)
        return 1

    leds = args.leds if args.leds and args.leds > 1 else device_led_count()
    bri = args.bri if args.bri else SCENES[name][2]
    bri = max(1, min(255, bri))

    if args.mid:
        try:
            hex_to_rgb(args.mid)
        except ValueError as exc:
            print(f"错误：--mid {exc}", file=sys.stderr)
            return 1

    recipe = build_recipe(name, start_hex, end_hex, leds, bri, args.profile, args.mid)

    if args.apply:
        return apply_recipe(recipe, args.dry_run)

    payload = recipe if args.emit == "recipe" else emit_state(recipe)
    print(json.dumps(payload, ensure_ascii=False, indent=2))
    return 0


if __name__ == "__main__":
    sys.exit(main())
# AI: end
